-- ULTIMATE FIX: Payment Slip Upload RLS\n-- Run this EXACT script in Supabase SQL Editor\n\n-- Clean slate\nDROP POLICY IF EXISTS \"Allow uploads payment-proofs\" ON storage.objects;\n\n-- IDENTICAL to working medical-reports policy\nCREATE POLICY \"Allow uploads payment-proofs\" ON storage.objects\nFOR INSERT\nTO service_role, authenticated, anon\nWITH CHECK (bucket_id = 'payment-proofs');\n\n-- Verify\nSELECT policyname, roles, cmd, qual \nFROM pg_policies \nWHERE tablename = 'objects' AND policyname LIKE '%payment%';\n\nSELECT 'FIX APPLIED ✅' as status;
